package com.example.bmmoney;
import android.app.*;import android.content.*;import android.graphics.Color;import android.os.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.bmmoney.data.*;import com.github.mikephil.charting.charts.*;import com.github.mikephil.charting.data.*;import com.github.mikephil.charting.formatter.*;import java.text.*;import java.util.*;
public class ReportActivity extends AppCompatActivity{private AppDatabase db;private final NumberFormat money=NumberFormat.getCurrencyInstance(new Locale("vi","VN"));@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_report);ThemeManager.apply(this);db=AppDatabase.getInstance(this);setupNav();findViewById(R.id.fabCreateReport).setOnClickListener(v->showCreateReportPopup());loadReport();}@Override protected void onResume(){super.onResume();if(db!=null)loadReport();}private void loadReport(){setupSummary();setupPie();setupBar();}private void setupSummary(){double income=0,expense=0;for(TypeTotal t:db.transactionDao().getTotalByType()){if("INCOME".equals(t.type))income=t.total;if("EXPENSE".equals(t.type))expense=t.total;}((TextView)findViewById(R.id.tvReportBalance)).setText(money.format(income-expense));((TextView)findViewById(R.id.tvReportIncome)).setText("Thu\n"+money.format(income));((TextView)findViewById(R.id.tvReportExpense)).setText("Chi\n"+money.format(expense));}private void setupPie(){PieChart chart=findViewById(R.id.pieChart);ArrayList<PieEntry> entries=new ArrayList<>();for(CategoryTotal c:db.transactionDao().getExpenseByCategory())if(c.total>0)entries.add(new PieEntry((float)c.total,c.category));if(entries.isEmpty())entries.add(new PieEntry(1,"Chưa có dữ liệu"));PieDataSet set=new PieDataSet(entries,"");set.setColors(new int[]{Color.rgb(188,108,37),Color.rgb(96,108,56),Color.rgb(221,161,94),Color.rgb(40,54,24),Color.rgb(160,146,90)});set.setValueTextColor(Color.rgb(40,54,24));set.setValueTextSize(11f);chart.setData(new PieData(set));chart.setDrawHoleEnabled(true);chart.setHoleColor(Color.rgb(254,250,224));chart.setCenterText("Chi tiêu\ntheo danh mục");chart.setCenterTextColor(Color.rgb(40,54,24));chart.getDescription().setEnabled(false);chart.getLegend().setTextColor(Color.rgb(96,108,56));chart.invalidate();}private void setupBar(){BarChart chart=findViewById(R.id.barChart);double income=0,expense=0;for(TypeTotal t:db.transactionDao().getTotalByType()){if("INCOME".equals(t.type))income=t.total;else if("EXPENSE".equals(t.type))expense=t.total;}ArrayList<BarEntry> entries=new ArrayList<>();entries.add(new BarEntry(0,(float)income));entries.add(new BarEntry(1,(float)expense));BarDataSet set=new BarDataSet(entries,"");set.setColors(new int[]{Color.rgb(96,108,56),Color.rgb(188,108,37)});set.setValueTextColor(Color.rgb(40,54,24));BarData data=new BarData(set);data.setBarWidth(.42f);chart.setData(data);chart.getDescription().setEnabled(false);chart.getLegend().setEnabled(false);chart.getAxisRight().setEnabled(false);chart.getAxisLeft().setTextColor(Color.rgb(96,108,56));chart.getXAxis().setValueFormatter(new IndexAxisValueFormatter(new String[]{"Thu","Chi"}));chart.getXAxis().setTextColor(Color.rgb(96,108,56));chart.invalidate();}private void showCreateReportPopup(){Toast.makeText(this,"Đã cập nhật báo cáo",Toast.LENGTH_SHORT).show();loadReport();}private void setupNav(){findViewById(R.id.navHome).setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));findViewById(R.id.navAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));findViewById(R.id.navReport).setOnClickListener(v->loadReport());findViewById(R.id.navSearch).setOnClickListener(v->startActivity(new Intent(this,SearchActivity.class)));findViewById(R.id.navSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}}
